"use client";

import { useEffect, useRef, useState } from "react";

/**
 * ReviewCarousel — a compact, auto-sliding single-card carousel for the
 * homepage's social-proof section. Both review sources (real, approved
 * <CustomerReviews/> and the illustrative <Testimonials/> fallback) used to
 * render as a full grid of up to 6 cards each — with both sources live at
 * once that's up to 12 stacked cards, a major contributor to homepage length.
 * This condenses either source down to one card's worth of vertical space,
 * auto-advancing through the rest.
 *
 * Deliberately simple compared to the game-cover coverflow carousel — no
 * drag/momentum, just a timed crossfade + slide, dot indicators, and the same
 * autoplay-pause rules used elsewhere on the site (hover, focus, tab-hidden,
 * prefers-reduced-motion).
 */

export type ReviewCarouselItem = {
  id: string;
  quote: string;
  name: string;
  meta: string;
  avatar: string; // initial letter or emoji
  rating?: number; // 1-5; omitted → no star row (illustrative use-cases)
};

function Stars({ rating }: { rating: number }) {
  const filled = Math.max(0, Math.min(5, rating));
  return (
    <span className="text-sm tracking-wide" aria-hidden>
      <span className="text-amber-400">{"★".repeat(filled)}</span>
      <span className="text-slate-700">{"★".repeat(5 - filled)}</span>
    </span>
  );
}

export function ReviewCarousel({ items, intervalMs = 5200 }: { items: ReviewCarouselItem[]; intervalMs?: number }) {
  const n = items.length;
  const [active, setActive] = useState(0);
  const [paused, setPaused] = useState(false);
  const reducedRef = useRef(false);
  const activeRef = useRef(0);

  useEffect(() => {
    reducedRef.current = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
  }, []);

  useEffect(() => {
    if (paused || reducedRef.current || n <= 1) return;
    const id = window.setInterval(() => {
      if (document.hidden) return;
      const next = activeRef.current + 1 >= n ? 0 : activeRef.current + 1;
      activeRef.current = next;
      setActive(next);
    }, intervalMs);
    return () => window.clearInterval(id);
  }, [paused, n, intervalMs]);

  if (n === 0) return null;

  const go = (i: number) => {
    const idx = ((i % n) + n) % n;
    activeRef.current = idx;
    setActive(idx);
  };

  const t = items[active];

  return (
    <div
      className="mx-auto max-w-2xl"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocusCapture={() => setPaused(true)}
      onBlurCapture={() => setPaused(false)}
    >
      <div
        role="group"
        aria-roledescription="carousel"
        aria-label="Customer reviews"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "ArrowLeft") go(active - 1);
          else if (e.key === "ArrowRight") go(active + 1);
        }}
        className="card relative min-h-[13rem] overflow-hidden outline-none focus-visible:ring-2 focus-visible:ring-brand-500/40"
      >
        <div key={t.id} className="flex h-full flex-col items-center text-center motion-safe:animate-[var(--animate-price-pop)]">
          {t.rating != null && <Stars rating={t.rating} />}
          <p className="mt-4 flex-1 text-sm leading-relaxed text-slate-300">&ldquo;{t.quote}&rdquo;</p>
          <div className="mt-5 flex flex-col items-center gap-2 border-t border-white/[0.06] pt-4">
            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-accent-blue/30 to-brand-500/30 text-base font-semibold text-brand-200">
              {t.avatar}
            </span>
            <span className="min-w-0">
              <span className="block text-sm font-semibold text-white">{t.name}</span>
              <span className="block text-xs text-slate-500">{t.meta}</span>
            </span>
          </div>
        </div>
      </div>

      {/* Live region so screen readers hear the review change without re-announcing the whole card. */}
      <p className="sr-only" aria-live="polite">
        Review {active + 1} of {n}: {t.name}
      </p>

      {n > 1 && (
        <div className="mt-4 flex items-center justify-center gap-2">
          {items.map((it, i) => (
            <button
              key={it.id}
              type="button"
              aria-label={`Show review ${i + 1} of ${n}`}
              aria-current={i === active}
              onClick={() => go(i)}
              className={`h-1.5 rounded-full transition-all ${i === active ? "w-6 bg-brand-400" : "w-1.5 bg-white/25 hover:bg-white/45"}`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

