import { db } from '/opt/nxeon/lib/db.ts';

const DONE_COL = 'cmsavdblw000dhla4dfb3n79h'; // Nxeon board / Done
const REVIEW_COL = 'cmsavdblw000chla4g6fdjg8h'; // Nxeon board / Review

async function moveCard(cardId, columnId, comment) {
  // append to end of target column
  const maxPos = await db.card.aggregate({
    where: { columnId },
    _max: { position: true },
  });
  const position = (maxPos._max.position ?? -1) + 1;
  await db.card.update({
    where: { id: cardId },
    data: { columnId, position },
  });
  if (comment) {
    await db.cardComment.create({
      data: { cardId, authorName: 'claude', body: comment },
    });
  }
  console.log('moved', cardId, '->', columnId);
}

async function main() {
  await moveCard(
    'cmterq6qg00lbhlsi3c6tjell',
    DONE_COL,
    'Implemented: removed the "Included on every plan" TrustBadges section and the "Pick your product. See the price." heading/price-lock badge from app/page.tsx, matching the two cropped screenshots exactly. Kept the "The right server for every workload" eyebrow line and the PricingExplorer itself (unchanged). Verified visually with a local dev server + Playwright screenshot. tsc clean, no new test failures.'
  );
  await moveCard(
    'cmterr33l00lphlsibpgl0s4u',
    DONE_COL,
    'Implemented: built a new auto-sliding, one-review-at-a-time <ReviewCarousel/> (components/marketing/ReviewCarousel.tsx) and switched both CustomerReviews.tsx and Testimonials.tsx to render through it instead of a 2/3-column grid — condenses the "Loved by builders" section from up to 12 stacked cards (real+illustrative) down to one card with dot indicators. Autoplay pauses on hover/focus/tab-hidden and is disabled under prefers-reduced-motion, matching the pattern used by the existing GameCoverCarousel. Verified visually (the currently-live illustrative fallback path, since no real reviews/testimonials are published yet). tsc clean, no new test failures.'
  );
  await moveCard(
    'cmterryie00m0hlsivinzwg7f',
    DONE_COL,
    'Implemented: added an icon above each of the 6 stat-bar figures in app/page.tsx (STATS array), using the same gradient icon-chip style as TrustBadges/PERF elsewhere on the page (IconBolt, IconGauge, IconNvme, IconScale, IconBackup, IconClock). Verified visually with a local dev server + Playwright screenshot. tsc clean, no new test failures.'
  );
  await moveCard(
    'cmtert3vz00mjhlsi9w3m9x0u',
    REVIEW_COL,
    'FLAGGED, NOT IMPLEMENTED: the screenshot points at the LogoMarquee.tsx trademark/nominative-use disclaimer ("All names and logos are the trademarks of their respective owners... No affiliation, partnership, sponsorship or endorsement is implied."). That paragraph exists specifically to protect Nxeon from implying sponsorship/partnership by the real third-party trademark holders shown in the logo strip (Docker, WordPress, Stripe, etc.) — the component\'s own doc comment calls this out as deliberate. Removing it as literally requested looks like a legal/brand risk rather than a copy cleanup, so I left it in place and moved this card to Review for a human call instead of Done. If the intent was something narrower (e.g. shortening the wording, or moving it somewhere less prominent) please clarify and I can implement that instead.'
  );
  await moveCard(
    'cmteruexl00mzhlsifpg0hntm',
    DONE_COL,
    'Implemented: in components/marketing/PricingExplorer.tsx, the "Trust footer" row below the pricing cards repeated 3 of the 5 "Included with all plans" chips shown directly above it (DDoS protected / Auto backups / NVMe everywhere, for the VPS tab). Replaced those 3 duplicate items with two facts not already covered there (99.9% uptime SLA, 24/7 platform monitoring) — both already truthfully claimed elsewhere on the homepage (hero checklist + stat bar), not new invented figures, matching this file\'s honesty-first pattern. Verified visually with a local dev server + Playwright screenshot. tsc clean, no new test failures.'
  );
}
main().then(() => process.exit(0)).catch(e => { console.error(e); process.exit(1); });
EOF
